describe('File Upload - Maximum Size Limit Error', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display error message when file exceeds maximum size limit', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 200,
      body: {
        error: 'File size exceeds maximum limit of 5MB',
        message: 'Please upload a file smaller than 5MB.'
      }
    }).as('uploadFile');

    // Attach a large file (e.g., 10MB)
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/large-file.zip', {
      force: true
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'File size exceeds maximum limit');

    // Verify error icon is visible
    cy.get('[data-testid="error-icon"]').should('be.visible');

    // Verify file input is still visible and user can retry
    cy.get('[data-testid="file-input"]').should('be.visible');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify retry button works
    cy.get('[data-testid="retry-button"]').click();
    cy.get('[data-testid="error-message"]').should('not.exist');
  });

  it('should not display error message when file is within size limit', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 200,
      body: {
        success: true,
        message: 'File uploaded successfully'
      }
    }).as('uploadFile');

    // Attach a small file (e.g., 1MB)
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/small-file.pdf', {
      force: true
    });

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File uploaded successfully');

    // Verify error message is not displayed
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify file input is still visible
    cy.get('[data-testid="file-input"]').should('be.visible');

    // Verify retry button is not visible
    cy.get('[data-testid="retry-button"]').should('not.exist');
  });
});
